@namespace sv_c27665e0ad724fd9a5e1ac892abd5d53.Components.Pages.Apply

<section class="step-section">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullNameChanged.InvokeAsync((string?)e.Value ?? "")" />
    </div>

    <div class="form-group">
        <label>Email Address *</label>
        <input type="email" value="@Email" @onchange="e => EmailChanged.InvokeAsync((string?)e.Value ?? "")" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone Number *</label>
        <input type="tel" value="@Phone" @onchange="e => PhoneChanged.InvokeAsync((string?)e.Value ?? "")" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => AddressChanged.InvokeAsync((string?)e.Value ?? "")"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
