@namespace sv_c27665e0ad724fd9a5e1ac892abd5d53.Components.Pages.Apply

<section class="step-section review-section">
    <h3>Review Your Application</h3>

    @if (Submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h4>Application Submitted!</h4>
            <p>Your application ID is <strong>#@ApplicationId</strong></p>
            <p>We'll be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-block">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-block">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="entry-desc">@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-error">@SubmitError</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" disabled="@IsSubmitting" @onclick="OnSubmit">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool Submitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? SubmitError { get; set; }

    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
}

