    color: #64748b;
    font-size: 0.8rem;
}

.entry-desc {
    margin: 0.25rem 0 0;
    color: #475569;
    font-size: 0.8rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
    max-height: 12rem;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation-icon {
    width: 3rem;
    height: 3rem;
    border-radius: 50%;
    background: #16a34a;
