toolArgs.file_text:
.apply-container {
    max-width: 48rem;
    margin: 2rem auto;
    padding: 1.5rem;
}

.apply-container h2 {
    text-align: center;
    margin-bottom: 1.5rem;
    color: #1e293b;
}

/* Step sections */
.step-section {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-section h3 {
    margin-top: 0;
    color: #1e293b;
    border-bottom: 1px solid #e2e8f0;
    padding-bottom: 0.75rem;
    margin-bottom: 1.25rem;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #374151;
    font-size: 0.875rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

.btn-primary {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.875rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.875rem;
}

.btn-outline:hover {
    background: #f9fafb;
}

.btn-secondary {
    background: #f1f5f9;
    color: #2563eb;
    border: 1px solid #cbd5e1;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    margin-top: 0.5rem;
}

.btn-secondary:hover {
    background: #e2e8f0;
}

.btn-remove {
    background: none;
    border: none;
    color: #dc2626;
    cursor: pointer;
    font-size: 0.8rem;
    padding: 0.25rem 0.5rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.8rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-error {
    background: #fef2f2;
    color: #dc2626;
    border: 1px solid #fecaca;
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    margin-top: 0.75rem;
}

.field-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work entry / Reference forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8fafc;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h4,
.reference-form h4 {
    margin: 0 0 0.75rem 0;
    font-size: 0.9rem;
    color: #475569;
}

/* Cover letter */
.cover-letter-textarea {
    min-height: 16rem;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #64748b;
    margin-top: 0.25rem;
}

.char-count.warning {
    color: #d97706;
    font-weight: 500;
}

/* Review step */
.review-block {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h4 {
    margin: 0;
    color: #1e293b;
}

.review-block dl {
    display: grid;
    grid-template-columns: 6rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
    font-size: 0.875rem;
}

.review-block dt {
    font-weight: 500;
    color: #64748b;
}

.review-block dd {
    margin: 0;
    color: #1e293b;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f1f5f9;
    font-size: 0.875rem;
}

.review-entry:last-child {
    border-bottom: none;
}

.date-range {
    color: #64748b;
    font-size: 0.8rem;
}

.entry-desc {
    margin: 0.25rem 0 0;
    color: #475569;
    font-size: 0.8rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
    max-height: 12rem;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation-icon {
    width: 3rem;
    height: 3rem;
    border-radius: 50%;
    background: #16a34a;
    color: white;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.confirmation h4 {
    color: #16a34a;
    margin: 0 0 0.5rem;
}

.hint {
    color: #64748b;
    font-size: 0.875rem;
    margin-top: 0;
}

