    private bool IsCurrent => Entry.EndDate is null;

    private void UpdateEntry(WorkEntry updated) => OnEntryChanged.InvokeAsync(updated);

    private void OnCompanyChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Company = e.Value?.ToString() ?? "" });

    private void OnTitleChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Title = e.Value?.ToString() ?? "" });

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            UpdateEntry(Entry with { StartDate = date });
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val) });
    }

    private void OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        UpdateEntry(updated);
    }

    private void OnDescriptionChanged(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Description = e.Value?.ToString() ?? "" });
}

